/**
 * @summary Webhook de Phir-it - sincroniza el estado de un estudio (pendiente/informado). Al pasar a informado dispara el WhatsApp al paciente (una sola vez por estudio).
 */
export const SyncPhiritEstudioBody = zod.object({
  "externalId": zod.string().describe('Identificador del estudio en Phir-it'),
  "estado": zod.enum(['pendiente', 'informado']),
  "patientId": zod.number().optional().describe('ID del paciente en Conectar (alternativa a pacienteDni)'),
  "pacienteDni": zod.string().optional().describe('DNI del paciente (alternativa a patientId)'),
  "descripcion": zod.string().optional(),
  "informeUrl": zod.string().optional().describe('URL del informe\/visor en Phir-it (Conectar no almacena el informe)'),
  "fechaCambio": zod.string().optional().describe('Fecha\/hora del cambio de estado en Phir-it (ISO 8601); si falta se usa la actual')
})

export const SyncPhiritEstudioResponse = zod.object({
  "estudio": zod.object({
  "id": zod.number(),
  "origen": zod.string(),
  "externalId": zod.string(),
  "patientId": zod.number(),
  "pacienteNombre": zod.string().nullish(),
  "descripcion": zod.string().nullish(),
  "estado": zod.string(),
  "informeUrl": zod.string().nullish(),
  "estadoCambiadoEn": zod.string().nullish(),
  "informadoEn": zod.string().nullish(),
  "notificadoEn": zod.string().nullish(),
  "notificacionId": zod.number().nullish(),
  "notificacionEstado": zod.string().nullish().describe('Estado de entrega del WhatsApp (enviada\/fallida\/simulada) si hubo notificación'),
  "tieneInformePdf": zod.boolean().optional().describe('true si el PDF del informe ya fue descargado del portal Phir-it y guardado en la nube'),
  "informePdfEn": zod.string().nullish().describe('Fecha\/hora en que el PDF del informe se guardó en la nube'),
  "createdAt": zod.coerce.date()
}),
  "notificacionDisparada": zod.boolean().describe('true solo si este evento generó el WhatsApp (dedupe por estudio)')
})


